window.MG_LAZY_DATA=window.MG_LAZY_DATA||Object.create(null);
window.MG_LAZY_DATA["data/lazy/courses/c407-e12958a399617dc4.json"]={sha256:"e12958a399617dc4c808c3f1593a6bb0dc986b4756f1f313b7b8d8e4129ab42e",value:{"id":"c407","title":"Universal Robots UR5 協作手臂","titleEn":"Universal Robots UR5 collaborative arm","category":"manufacturing","summary":"以UR5系列的公開歷史為入口，透過紙上六軸工作站概念學習座標框、TCP、負載力矩、路徑與狀態確認，先掌握整合問題。","summaryEn":"Enter through the public history of the UR5 family and use paper workcell concepts to study frames, TCP, payload moments, paths and state confirmation before integration.","scope":"12道紙上與示意任務，不操作實體機器。UR5e公開手冊僅支援通用概念，不能直接當作原始UR5或其他版本SOP；實際應用仍需對應手冊、合格整合及現場風險驗證。","scopeEn":"Twelve paper and schematic tasks without physical robot operation. UR5e documentation supports general concepts and is not an SOP for the original UR5 or other revisions. Actual applications require matching manuals, qualified integration and on-site risk validation.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-ur-history","v6-ur5e-manual","v6-ur-odense"],"diagram":{"type":"robot","labels":["工作站需求","座標與TCP","負載與路徑","事件與停止","配置證據"],"labelsEn":["Workcell needs","Frames and TCP","Payload and path","Events and stopping","Configuration evidence"],"original":true,"notToScale":true},"depth":4,"stages":[{"id":"c407-stage01","order":1,"title":"應用邊界、座標與工具","titleEn":"Application boundary, frames and tool","description":"先辨識整個工作站，再分清參考框架、工具中心及負載。","descriptionEn":"Identify the whole workcell, then distinguish reference frames, TCP and payload.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c407-v6-01","order":1,"sequence":1,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":[],"sourceIds":["v6-ur5e-manual"],"title":"界定協作工作站的風險邊界","titleEn":"Define the collaborative workcell risk boundary","objective":"把手臂、工具、工件與人員入口共同納入場域圖。","objectiveEn":"Include the arm, tool, workpiece and human access in the workcell map.","instruction":"在原創紙上工作站放置六軸手臂、夾具、假設工件與人員入口。以不同標記圈出掃掠、夾擠與掉落情境；閱讀公開手冊的應用風險觀念，不啟動實體機器。","instructionEn":"On an original paper workcell, place a six-axis arm, fixture, hypothetical part and human entrance. Mark swept-space, trapping and dropped-object scenarios. Study public application-risk concepts without powering physical machinery.","observation":"協作手臂的名稱不會消除末端工具與周邊設備造成的危害。","observationEn":"A collaborative-arm label does not remove hazards from tools and surrounding equipment.","failure":"只圈手臂本體、漏掉工件及夾具，會縮小了風險分析邊界。","failureEn":"Mapping only the arm omits workpiece and fixture hazards from the assessment boundary.","check":"至少標出三類危害及暴露情境，列明需由合格整合者評估。","checkEn":"Mark at least three hazard types and exposure scenarios, identifying the need for qualified integration assessment.","knowledge":[{"id":"c407-v6-01-k1","title":"應用層級","titleEn":"Application level","text":"機器人安全與工具、工件、環境及使用方式共同相關。","textEn":"Application safety depends on tools, workpieces, environment and use as well as the robot."},{"id":"c407-v6-01-k2","title":"生命周期","titleEn":"Lifecycle","text":"示教、正常運轉與維修可能有不同的暴露情境。","textEn":"Teaching, normal operation and maintenance can create different exposures."}],"quiz":{"question":"哪項判斷應退回重新評估？","questionEn":"Which conclusion should be rejected for reassessment?","options":["工具及工件危害需一併辨識","維修暴露情境需另外列入評估","因產品名稱含「協作」，所以不需應用風險評估"],"optionsEn":["Tool and workpiece hazards need to be identified together","Maintenance exposure scenarios need explicit assessment","Because the product is called collaborative, no application risk assessment is needed"],"answer":2,"explanation":"名稱不能取代應用風險評估與驗證。","explanationEn":"A label cannot replace application risk assessment and validation."}},{"id":"c407-v6-02","order":2,"sequence":2,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-01"],"sourceIds":["v6-ur5e-manual"],"title":"建立基座與工件座標框","titleEn":"Establish base and workpiece frames","objective":"用明確原點與方向描述同一位置。","objectiveEn":"Describe one position with explicit origins and axes.","instruction":"畫基座XY與旋轉90°的工件XY座標。用同一支向右的世界方向箭頭，分別表示它在兩個框架的分量；標明正轉方向，先做平面概念再談六軸。","instructionEn":"Draw base XY axes and a workpiece frame rotated 90°. Express one rightward world arrow in both frames, stating positive rotation. Begin with planar concepts before considering six axes.","observation":"同一實體方向的座標分量會隨參考框架改變。","observationEn":"Coordinates of the same physical direction change with the reference frame.","failure":"切換框架卻沿用舊分量，會讓工具朝錯誤方向移動。","failureEn":"Changing frames while reusing old components moves the tool in the wrong direction.","check":"兩套箭頭都有原點、軸名與旋轉定義，能描述同一實體方向。","checkEn":"Both frames have origins, axis names and rotation definitions representing the same direction.","knowledge":[{"id":"c407-v6-02-k1","title":"座標與物理","titleEn":"Coordinates and physics","text":"座標是描述方式，切換座標不代表物件自己移動。","textEn":"Coordinates are a description; changing them does not itself move an object."},{"id":"c407-v6-02-k2","title":"參考框架","titleEn":"Reference frame","text":"指令的方向必須和其使用的框架一起解讀。","textEn":"A commanded direction must be interpreted with its frame."}],"quiz":{"question":"座標值改變就必然代表工具移動了嗎？","questionEn":"Do changed coordinate values necessarily mean the tool moved?","options":["一定，任何座標數字變化都是實體位移","不一定，可能只是換了參考框架","只有平移原點會改座標，旋轉軸向不會"],"optionsEn":["Yes; every coordinate change is physical displacement","No; the reference frame may have changed","Only moving the origin changes coordinates, not rotating the axes"],"answer":1,"explanation":"同一姿態可以有不同框架下的描述。","explanationEn":"One pose can have different descriptions in different frames."}},{"id":"c407-v6-03","order":3,"sequence":3,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-02"],"sourceIds":["v6-ur5e-manual"],"title":"標定工具中心的概念偏移","titleEn":"Model a tool-center offset","objective":"把法蘭位置與实际工作點分開。","objectiveEn":"Separate flange position from the working point.","instruction":"畫末端法蘭與向前延伸2教學單位的工具尖端。保持法蘭位置不變，將工具方向在紙上轉90°，比較尖端位置；用此說明為何TCP定義包含相對位置。","instructionEn":"Sketch a flange and tool tip extending 2 teaching units. Hold flange position fixed and rotate the tool orientation by 90° on paper. Compare tip locations to explain why TCP definition includes an offset.","observation":"法蘭中心不移動，偏置工具尖端仍會移動。","observationEn":"An offset tool tip moves even if the flange center does not.","failure":"把法蘭原點當作所有工具的尖端，会造成系統性定位誤差。","failureEn":"Treating the flange origin as every tool’s tip creates systematic positioning error.","check":"兩種方向都畫出法蘭、偏移向量及TCP位置。","checkEn":"Show flange, offset vector and TCP in both orientations.","knowledge":[{"id":"c407-v6-03-k1","title":"TCP","titleEn":"Tool center point","text":"TCP是所選工具工作點的座標定義，不一定在法蘭中心。","textEn":"A TCP defines a selected working point and need not lie at the flange center."},{"id":"c407-v6-03-k2","title":"姿態影響","titleEn":"Orientation effect","text":"偏移向量需隨工具方向轉換到基座框架。","textEn":"The offset vector must be transformed with tool orientation into the base frame."}],"quiz":{"question":"換上更長工具而未更新TCP，最可能出現什麼？","questionEn":"A longer tool is fitted without updating TCP. What is a likely result?","options":["實際工作點偏離預期位置","工具長度不影響幾何","所有關節角自動歸零"],"optionsEn":["The physical working point misses the intended location","Tool length has no geometric effect","All joint angles automatically become zero"],"answer":0,"explanation":"TCP錯誤直接影響工作點的幾何描述。","explanationEn":"An incorrect TCP directly affects the working-point geometry."}},{"id":"c407-v6-04","order":4,"sequence":4,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-03"],"sourceIds":["v6-ur5e-manual"],"title":"比較負載質量與重心位置","titleEn":"Compare payload mass and center of mass","objective":"理解相同質量在不同偏移下的力矩差異。","objectiveEn":"Understand different moments from equal mass at different offsets.","instruction":"用平面示意將同一教學負載放在距法蘭1與3單位的位置，保持重力方向不變。比較力矩倍率，再列出工具、工件與夾具是否都已計入；不選實機負載參數。","instructionEn":"Place the same teaching load at offsets 1 and 3 from a flange in a planar sketch, keeping gravity direction fixed. Compare moments and check inclusion of tool, part and gripper mass. Do not select physical robot payload settings.","observation":"垂直力臂增加3倍，靜態重力矩也增加3倍。","observationEn":"Tripling the perpendicular lever arm triples the static gravitational moment.","failure":"只輸入工件重量卻漏掉夾具，會錯估負載。","failureEn":"Entering only workpiece mass while omitting the gripper misrepresents the load.","check":"負載表包含各物件質量與相對重心，未有數值者標待查。","checkEn":"Include each item’s mass and relative center, marking unavailable values pending.","knowledge":[{"id":"c407-v6-04-k1","title":"質量與力矩","titleEn":"Mass and moment","text":"質量相同不代表關節承受相同力矩。","textEn":"Equal mass does not imply equal joint moment."},{"id":"c407-v6-04-k2","title":"組合負載","titleEn":"Combined payload","text":"工具與工件共同形成末端負載及重心。","textEn":"Tool and workpiece jointly define payload and its center."}],"quiz":{"question":"同一重量離支點的垂直距離從1變3，靜態力矩如何變？","questionEn":"For equal weight, perpendicular offset increases from 1 to 3. How does static moment change?","options":["保持不變","變成1/3","成為3倍"],"optionsEn":["It stays unchanged","It becomes one third","It triples"],"answer":2,"explanation":"靜態力矩等於力乘垂直力臂。","explanationEn":"Static moment equals force times perpendicular lever arm."}}]},{"id":"c407-stage02","order":2,"title":"運動幾何與可行路徑","titleEn":"Motion geometry and feasible paths","description":"用平面例子檢查插補、掃掠空間、奇異性與姿態可行性。","descriptionEn":"Use planar examples to examine interpolation, swept space, singularity and pose feasibility.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c407-v6-05","order":1,"sequence":5,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-04"],"sourceIds":["v6-ur5e-manual"],"title":"分辨關節運動與工具直線","titleEn":"Distinguish joint motion from a straight tool path","objective":"理解端點軌跡與關節插補不是同一問題。","objectiveEn":"Understand that tool trajectory and joint interpolation differ.","instruction":"用兩節平面手臂畫起終姿態。先讓兩關節角均勻改變，標出中間工具位置；再畫工具沿直線的目標路徑，比較兩條曲線，不宣稱已解真機逆運動學。","instructionEn":"Use a two-link planar arm with start and end poses. Vary joint angles uniformly and mark intermediate tool positions, then draw a desired straight tool path and compare. Do not claim to solve the real robot’s inverse kinematics.","observation":"關節平順變化不保證工具端點走直線。","observationEn":"Smooth joint changes do not guarantee a straight endpoint path.","failure":"只核對起终點而忽略中間軌跡，可能漏掉障礙碰撞。","failureEn":"Checking only endpoints can miss intermediate collisions.","check":"兩種路徑至少各有一個中間姿態，並記錄差異。","checkEn":"Include at least one intermediate pose for each path and record the difference.","knowledge":[{"id":"c407-v6-05-k1","title":"正運動學","titleEn":"Forward kinematics","text":"關節配置映射到工具姿態，映射通常不是線性的。","textEn":"Joint configuration maps to tool pose, generally nonlinearly."},{"id":"c407-v6-05-k2","title":"路徑要求","titleEn":"Path requirement","text":"應用可能要求端點幾何路徑，而非只要求抵達終點。","textEn":"An application may require a particular tool path, not just an endpoint."}],"quiz":{"question":"關節角等速改變，工具必定走直線嗎？","questionEn":"Do uniformly changing joint angles guarantee a straight tool path?","options":["必然，關節插補與工具直線完全相同","不必然","只要兩關節角速度相同就保證直線"],"optionsEn":["Yes; joint interpolation and a tool straight line are identical","No","Equal joint angular speeds guarantee a straight tool path"],"answer":1,"explanation":"關節空間到工具空間的映射通常非線性。","explanationEn":"The joint-to-tool mapping is generally nonlinear."}},{"id":"c407-v6-06","order":2,"sequence":6,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-05"],"sourceIds":["v6-ur5e-manual"],"title":"用過渡點檢查完整掃掠空間","titleEn":"Check swept space with intermediate poses","objective":"把工具與每節連桿都納入路徑檢查。","objectiveEn":"Include the tool and every link in path checks.","instruction":"在紙上加入一個障礙物，畫出起點、過渡點與終點的完整手臂。給工具加上假設工件輪廓，逐一比較掃掠空間；所有距離均為教學示意。","instructionEn":"Add an obstacle to the paper workcell and draw the complete arm at start, intermediate and end poses. Include a hypothetical carried part and compare swept spaces using teaching distances only.","observation":"工具尖端避開障礙，手肘或工件仍可能相交。","observationEn":"The tip may clear an obstacle while an elbow or carried part intersects it.","failure":"只檢查TCP軌跡，會忽略其他運動部位。","failureEn":"Checking only TCP trajectory omits other moving parts.","check":"每個姿態都標出最接近障礙的部位及尚未驗證的連續區間。","checkEn":"Identify the closest part at each pose and any continuous intervals not yet checked.","knowledge":[{"id":"c407-v6-06-k1","title":"掃掠體積","titleEn":"Swept volume","text":"運動物件沿路徑占據的空間超過一條端點線。","textEn":"The space occupied by a moving body exceeds an endpoint line."},{"id":"c407-v6-06-k2","title":"離散檢查限制","titleEn":"Discrete-check limitation","text":"少量姿態快照不能保證中間所有位置安全。","textEn":"A few pose snapshots cannot establish safety at every intermediate point."}],"quiz":{"question":"三張姿態圖都沒碰撞，能否保證整條路徑無碰撞？","questionEn":"If three pose snapshots are clear, is the entire path guaranteed collision-free?","options":["不能，中間區間仍需檢查","能，起點、中點及終點一定涵蓋全部軌跡","只需確認起終點高度相同"],"optionsEn":["No; intermediate intervals still need checking","Yes; start, middle and end always cover the whole path","Only equal start/end heights need confirmation"],"answer":0,"explanation":"離散取樣可能漏掉中間的相交。","explanationEn":"Discrete sampling can miss intersections between samples."}},{"id":"c407-v6-07","order":3,"sequence":7,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-06"],"sourceIds":["v6-ur5e-manual"],"title":"辨識接近奇異姿態的訊號","titleEn":"Recognize signs of a near-singular configuration","objective":"理解微小工具運動可能需要較大關節變化。","objectiveEn":"Understand why small tool motion can require large joint changes.","instruction":"以兩節平面手臂比較彎曲與幾乎伸直兩種姿態，畫出小幅工具位移，特別標示沿手臂伸展方向的分量。比較所需關節改變的敏感性；不計算或修改實機速度限制。","instructionEn":"Compare bent and nearly straight configurations of a two-link planar arm. Sketch a small tool displacement, explicitly marking its component along the extension direction. Compare sensitivity of required joint changes without calculating or changing real speed limits.","observation":"接近特定幾何排列時，位置與關節變化的關係可能變得敏感。","observationEn":"Near particular geometric alignments, the relation between position and joint changes can become sensitive.","failure":"把工具速度看似很小當作關節速度一定很小，會漏看幾何放大。","failureEn":"Assuming low tool speed guarantees low joint speeds overlooks geometric amplification.","check":"說明哪種姿態較需檢查敏感性，並記錄這只是平面示意。","checkEn":"Identify which configuration needs sensitivity review and label the planar simplification.","knowledge":[{"id":"c407-v6-07-k1","title":"奇異性","titleEn":"Singularity","text":"某些配置會使可用瞬時運動方向或逆解行為退化。","textEn":"Certain configurations degrade available instantaneous motion directions or inverse behavior."},{"id":"c407-v6-07-k2","title":"速度映射","titleEn":"Velocity mapping","text":"工具速度與關節速度經由姿態相關的映射連結。","textEn":"Tool and joint velocities are linked by a configuration-dependent mapping."}],"quiz":{"question":"接近奇異姿態時，哪個判斷最可靠？","questionEn":"Near a singular configuration, which judgment is most reliable?","options":["工具慢就保證所有關節慢","只要終點可達就忽略路徑","需檢查關節與工具運動的敏感性"],"optionsEn":["A slow tool guarantees every joint is slow","Ignore the path if the endpoint is reachable","Check sensitivity between joint and tool motion"],"answer":2,"explanation":"幾何映射可能放大關節運動需求。","explanationEn":"The geometric mapping can amplify joint-motion demand."}},{"id":"c407-v6-08","order":4,"sequence":8,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-07"],"sourceIds":["v6-ur5e-manual"],"title":"比較可達範圍與工作姿態","titleEn":"Compare reachability with working pose","objective":"把位置、方向與周邊限制分開核對。","objectiveEn":"Check position, orientation and surrounding constraints separately.","instruction":"畫一個可到達的目標點，再要求工具以指定方向接近。以兩個假設姿態比較是否同時滿足方向、工件空間與關節範圍；不推定任何UR5版本的實際可達界限。","instructionEn":"Draw a reachable target point and then require a specified approach orientation. Compare two hypothetical poses for orientation, part clearance and joint range, without inferring actual reach limits for any UR5 version.","observation":"同一位置可能只有部分工具方向可用。","observationEn":"Only some tool orientations may be usable at the same position.","failure":"把手臂最大伸展半徑當作完整可工作空間，忽略了姿態與障礙。","failureEn":"Treating maximum reach radius as the full usable workspace omits orientation and obstacles.","check":"對兩個姿態分別填入位置、方向、空間與關節條件。","checkEn":"Record position, orientation, clearance and joint conditions for both poses.","knowledge":[{"id":"c407-v6-08-k1","title":"姿態","titleEn":"Pose","text":"姿態包含位置及方向，不能只給三個位置座標。","textEn":"Pose includes position and orientation, not only three position coordinates."},{"id":"c407-v6-08-k2","title":"任務空間","titleEn":"Task workspace","text":"可工作的區域由應用條件共同限制。","textEn":"Usable workspace is constrained by the application’s combined conditions."}],"quiz":{"question":"為何只看伸展半徑不足以證明目標可作業？","questionEn":"Why is reach radius alone insufficient to establish task feasibility?","options":["半徑內所有工具方向均已被保證","還需找到符合方向、關節及空間條件的姿態","TCP到基座的距離會決定唯一關節配置"],"optionsEn":["Every tool orientation inside the radius is already guaranteed","A pose satisfying orientation, joint and clearance conditions is still needed","TCP distance from the base determines a unique joint configuration"],"answer":1,"explanation":"可達位置不等於可執行指定任務。","explanationEn":"Reaching a position does not mean performing the required task is feasible."}}]},{"id":"c407-stage03","order":3,"title":"確認、恢復與版本交付","titleEn":"Confirmation, recovery and version handover","description":"將感測握手、節拍、停止後狀態及配置紀錄組成可審查流程。","descriptionEn":"Build an auditable workflow from sensor handshakes, cycle time, post-stop state and configuration records.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c407-v6-09","order":1,"sequence":9,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-08"],"sourceIds":["v6-ur5e-manual"],"title":"建立夾取與感測的握手流程","titleEn":"Build a grasp-and-sensor handshake","objective":"讓指令與已確認的物件狀態分開。","objectiveEn":"Separate commands from confirmed object state.","instruction":"用紙上狀態圖表示待命、夾取指令、等待確認、搬移與異常。設一個感測確認未到的情境，停留在等待或異常分支；不寫入真實控制器。","instructionEn":"Create a paper state diagram for idle, grasp command, waiting for confirmation, transfer and fault. Withhold a sensor acknowledgment and remain in a waiting or fault branch. Do not program a physical controller.","observation":"已送出夾取指令不代表物件已被可靠握住。","observationEn":"Issuing a grasp command does not establish that the part is securely held.","failure":"固定等一小段時間就搬移，可能把未知狀態誤判成功。","failureEn":"Moving after a fixed short delay may mistake uncertainty for success.","check":"圖上每條搬移轉移都有確認條件，並有未確認分支。","checkEn":"Give each transfer transition a confirmation condition and an unconfirmed branch.","knowledge":[{"id":"c407-v6-09-k1","title":"狀態機","titleEn":"State machine","text":"流程依狀態與事件轉移，不只依時間順序。","textEn":"A process transitions through states and events, not just elapsed time."},{"id":"c407-v6-09-k2","title":"確認證據","titleEn":"Confirmation evidence","text":"感測回覆也有適用範圍與可能故障，需納入驗證。","textEn":"Sensor acknowledgment also has scope and failure modes requiring validation."}],"quiz":{"question":"夾取指令已送出但未收到確認，紙上流程應如何？","questionEn":"A grasp command is sent but unconfirmed. What should the paper workflow do?","options":["走等待或異常分支，不宣稱夾取完成","直接搬移並假設已夾住","固定等待後一律判為成功"],"optionsEn":["Follow a waiting or fault branch without declaring success","Move immediately and assume a successful grasp","Always declare success after a fixed delay"],"answer":0,"explanation":"指令不是完成證據。","explanationEn":"A command is not completion evidence."}},{"id":"c407-v6-10","order":2,"sequence":10,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-09"],"sourceIds":["v6-ur5e-manual"],"title":"比較節拍與驗證覆蓋","titleEn":"Compare cycle time with verification coverage","objective":"在簡化流程中辨識等待與搬移成本。","objectiveEn":"Identify waiting and motion costs in a simplified cycle.","instruction":"自訂教學週期：接近2秒、確認1秒、搬移3秒、放置2秒。計算總時間，再提出一個只改布局的縮時假設；保留確認步驟並標示尚需驗證。","instructionEn":"Use a teaching cycle of 2 s approach, 1 s confirmation, 3 s transfer and 2 s placement. Sum the time and propose a layout-only improvement, retaining confirmation and marking the proposal for validation.","observation":"總時間8秒；刪除確認雖縮時，卻改變功能保證。","observationEn":"Total time is 8 s; deleting confirmation reduces time but changes functional assurance.","failure":"為了節拍省略安全或品質關卡，不能算等條件改善。","failureEn":"Removing safety or quality gates is not a like-for-like improvement.","check":"比較前後需求相同，所有時間與新增假設明列。","checkEn":"Keep requirements equal and list timings and added assumptions.","knowledge":[{"id":"c407-v6-10-k1","title":"節拍分解","titleEn":"Cycle-time decomposition","text":"總時間由動作、等待與確認共同組成。","textEn":"Total time includes motion, waiting and confirmation."},{"id":"c407-v6-10-k2","title":"等條件比較","titleEn":"Like-for-like comparison","text":"改善必須保留原有需求，否則比較對象已改變。","textEn":"An improvement must retain requirements or the comparison target has changed."}],"quiz":{"question":"哪種縮時方案較適合先作紙上評估？","questionEn":"Which time-reduction idea is more suitable for initial paper evaluation?","options":["刪除夾取確認以縮短等待","未收到確認時直接略過該狀態","縮短布局搬移距離但保留驗證關卡"],"optionsEn":["Delete grasp confirmation to reduce waiting","Skip the state whenever confirmation is missing","Shorten transfer distance while retaining verification gates"],"answer":2,"explanation":"布局改善可在保留功能需求下提出，但仍需驗證。","explanationEn":"Layout changes can preserve functional requirements, but still require validation."}},{"id":"c407-v6-11","order":3,"sequence":11,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-10"],"sourceIds":["v6-ur5e-manual"],"title":"分析停止後的狀態與恢復","titleEn":"Analyze state after stopping and recovery","objective":"把停止命令與已停止、可重新啟動分開。","objectiveEn":"Separate a stop command, stopped state and restart readiness.","instruction":"在紙上選一個搬移中的時刻，標出工具、工件與外部設備的狀態。列出停止後仍需確認的位置、握持與人員情境，再畫「重新確認後」的恢復分支；不測試實機停距。","instructionEn":"Choose a point during the paper transfer cycle and mark tool, part and external-equipment states. List position, grasp and human-context checks after a stop, then draw a revalidated recovery branch. Do not test physical stopping distance.","observation":"停止運動不必然代表工件已穩定或周邊設備已處於相同狀態。","observationEn":"Stopped motion does not necessarily mean the part is secure or surrounding equipment is in a matching state.","failure":"直接回到原流程下一行，可能沿用已失效的狀態假設。","failureEn":"Resuming at the next program line may reuse invalid state assumptions.","check":"恢復分支包含重新確認條件與不確定時的處置。","checkEn":"Include revalidation conditions and an uncertainty response in recovery.","knowledge":[{"id":"c407-v6-11-k1","title":"停止過程","titleEn":"Stopping process","text":"發出停止指令與實際停止之間仍有動態過程。","textEn":"A dynamic process exists between a stop command and actual standstill."},{"id":"c407-v6-11-k2","title":"狀態恢復","titleEn":"State recovery","text":"恢復需要確認系統狀態，而非只記住程式位置。","textEn":"Recovery requires confirming system state, not just program position."}],"quiz":{"question":"停止後重新啟動前，哪個做法較完整？","questionEn":"Before restarting after a stop, which approach is more complete?","options":["假設所有外部設備同步停止","重新確認工件、設備與人員狀態","只讀取程式行號"],"optionsEn":["Assume every external device stopped synchronously","Reconfirm part, equipment and human states","Read only the program line number"],"answer":1,"explanation":"程式位置不足以代表實體系統狀態。","explanationEn":"Program position does not fully represent physical system state."}},{"id":"c407-v6-12","order":4,"sequence":12,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c407-v6-11"],"sourceIds":["v6-ur-history","v6-ur5e-manual","v6-ur-odense"],"title":"整理工具與程式的版本證據","titleEn":"Organize tool and program version evidence","objective":"避免把一個機型或工具的設定直接移植。","objectiveEn":"Avoid directly transplanting settings between models or tools.","instruction":"建立交付表，列手臂型號、手冊版本、工具TCP、負載假設、工件框架、程式版本與紙上驗證結果。注明UR5歷史課程引用UR5e手冊僅為概念參考，實際機型需另核對。","instructionEn":"Create a handover table with arm model, manual revision, TCP, payload assumptions, workpiece frame, program revision and paper-validation results. State that the historical UR5 course uses UR5e documentation conceptually; actual model compatibility needs separate checking.","observation":"程式檔一致而工具或安裝設定不同，仍可能產生不同運動。","observationEn":"Equal program files can produce different behavior with changed tool or installation settings.","failure":"只備份程式、不記錄安裝與工具配置，會留下復現缺口。","failureEn":"Backing up only the program without installation and tool configuration leaves a reproducibility gap.","check":"交付表能指出每一設定的來源與適用版本，不宣稱課程等於現場驗收。","checkEn":"Trace each setting to a source and applicable revision without equating the course to on-site acceptance.","knowledge":[{"id":"c407-v6-12-k1","title":"配置組合","titleEn":"Configuration set","text":"程式、工具、座標與負載設定共同定義應用。","textEn":"Program, tool, frames and payload settings jointly define the application."},{"id":"c407-v6-12-k2","title":"版本適用性","titleEn":"Version applicability","text":"相近產品名稱不保證介面、限制或程序相同。","textEn":"Similar product names do not guarantee identical interfaces, limits or procedures."}],"quiz":{"question":"只帶走程式檔，為何可能無法重現工作站？","questionEn":"Why may a program file alone fail to reproduce a workcell?","options":["工具與安裝設定也是應用的一部分","程式檔必定已包含所有機械工具尺寸","相同檔名就能保證相同安裝設定"],"optionsEn":["Tool and installation settings are also part of the application","A program file necessarily contains every physical tool dimension","An equal filename guarantees identical installation settings"],"answer":0,"explanation":"應用行為由整個配置組合決定。","explanationEn":"Application behavior depends on the complete configuration set."}}]}],"stepCount":12,"estimatedMinutes":216,"languageCoverage":["zh-TW","en"],"status":"guided","kind":"course","curriculumVersion":6}};
